[data-screen-root] {
  --c-bg: #fefefe;
  --c-surface: #ffffff;
  --c-text: #1d1a1f;
  --c-muted: #575552;
  --c-border: #e0e0e0;
  --c-accent: #e9c048;
  --c-on-accent: #1d1a1f;
  --font-body: "Roboto", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --fs-xs: 12px;
  --fs-sm: 14.5px;
  --fs-md: 27px;
  --fs-lg: 33px;
  --fs-xl: 40px;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 16px;

  font-family: var(--font-body);
  background-color: var(--c-bg);
  color: var(--c-text);
  font-size: var(--fs-sm);
  box-sizing: border-box;
  position: relative;
  width: 100%;
  height: 100%;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

[data-screen-root] *,
[data-screen-root] *::before,
[data-screen-root] *::after {
  box-sizing: inherit;
}

[data-screen-root] .app-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--c-surface);
  border-bottom: 1px solid var(--c-border);
  font-size: var(--fs-md);
  font-weight: 500;
}

[data-screen-root] .tab-bar {
  display: flex;
  background: var(--c-surface);
  border-top: 1px solid var(--c-border);
  height: 56px;
  position: sticky;
  bottom: 0;
  width: 100%;
  z-index: 10;
}

[data-screen-root] .tab {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--c-muted);
  font-size: var(--fs-xs);
  background: none;
  border: none;
  cursor: pointer;
  gap: 4px;
}

[data-screen-root] .tab.is-selected {
  color: var(--c-text);
  font-weight: 600;
}

[data-screen-root] .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 16px;
  border-radius: var(--r-md);
  font-size: var(--fs-sm);
  font-weight: 500;
  border: 1px solid transparent;
  cursor: pointer;
  background: none;
  color: var(--c-text);
}

[data-screen-root] .btn-primary {
  background: var(--c-accent);
  color: var(--c-on-accent);
}

[data-screen-root] .btn-secondary {
  background: var(--c-surface);
  border-color: var(--c-border);
}

[data-screen-root] .chip {
  display: inline-flex;
  align-items: center;
  padding: 6px 14px;
  border-radius: 9999px;
  background: #f0f0f0;
  color: var(--c-text);
  font-size: var(--fs-sm);
  border: none;
  cursor: pointer;
  white-space: nowrap;
}

[data-screen-root] .chip.is-selected,
[data-screen-root] .chip[aria-selected="true"] {
  background: var(--c-accent);
  color: var(--c-on-accent);
  font-weight: 500;
}

[data-screen-root] .counter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border-radius: 9999px;
  background: var(--c-accent);
  color: var(--c-on-accent);
  font-size: 10px;
  font-weight: 700;
}

[data-screen-root] .badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 6px;
  border-radius: var(--r-sm);
  background: #eee;
  color: var(--c-muted);
  font-size: var(--fs-xs);
}

[data-screen-root] .card {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--r-md);
  padding: 12px;
  margin-bottom: 12px;
}

[data-screen-root] .list-row {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  background: var(--c-surface);
  border-bottom: 1px solid var(--c-border);
  gap: 12px;
}

[data-screen-root] .bubble-in {
  background: #f0f0f0;
  color: var(--c-text);
  padding: 10px 14px;
  border-radius: var(--r-md);
  align-self: flex-start;
  max-width: 80%;
}

[data-screen-root] .bubble-out {
  background: var(--c-accent);
  color: var(--c-on-accent);
  padding: 10px 14px;
  border-radius: var(--r-md);
  align-self: flex-end;
  max-width: 80%;
}

[data-screen-root] .composer {
  display: flex;
  align-items: center;
  padding: 8px 16px;
  background: var(--c-surface);
  border-top: 1px solid var(--c-border);
  gap: 8px;
}

[data-screen-root] .scrim {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.4);
  z-index: 100;
  display: flex;
  align-items: flex-end;
}

[data-screen-root] .modal {
  background: var(--c-surface);
  border-radius: var(--r-lg);
  padding: 20px;
  width: 90%;
  max-width: 360px;
  margin: auto;
  z-index: 101;
}

[data-screen-root] .sheet {
  background: var(--c-surface);
  border-top-left-radius: var(--r-lg);
  border-top-right-radius: var(--r-lg);
  padding: 16px 20px 24px 20px;
  width: 100%;
  z-index: 101;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

[data-screen-root] .paywall {
  background: var(--c-surface);
  border-radius: var(--r-lg);
  padding: 24px;
  text-align: center;
  border: 1px solid var(--c-border);
}

[data-screen-root] .store-tile {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--r-md);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
